(14, 1, '2024-04-18 22:17:03', '2024-04-18 22:17:03', '<!-- wp:html -->\n  <svg xmlns=\"http://www.w3.org/2000/svg\" class=\"d-none\">\n    <symbol id=\"check2\" viewBox=\"0 0 16 16\">\n      <path\n        d=\"M13.854 3.646a.5.5 0 0 1 0 .708l-7 7a.5.5 0 0 1-.708 0l-3.5-3.5a.5.5 0 1 1 .708-.708L6.5 10.293l6.646-6.647a.5.5 0 0 1 .708 0z\" />\n    </symbol>\n    <symbol id=\"circle-half\" viewBox=\"0 0 16 16\">\n      <path d=\"M8 15A7 7 0 1 0 8 1v14zm0 1A8 8 0 1 1 8 0a8 8 0 0 1 0 16z\" />\n    </symbol>\n    <symbol id=\"moon-stars-fill\" viewBox=\"0 0 16 16\">\n      <path\n        d=\"M6 .278a.768.768 0 0 1 .08.858 7.208 7.208 0 0 0-.878 3.46c0 4.021 3.278 7.277 7.318 7.277.527 0 1.04-.055 1.533-.16a.787.787 0 0 1 .81.316.733.733 0 0 1-.031.893A8.349 8.349 0 0 1 8.344 16C3.734 16 0 12.286 0 7.71 0 4.266 2.114 1.312 5.124.06A.752.752 0 0 1 6 .278z\" />\n      <path\n        d=\"M10.794 3.148a.217.217 0 0 1 .412 0l.387 1.162c.173.518.579.924 1.097 1.097l1.162.387a.217.217 0 0 1 0 .412l-1.162.387a1.734 1.734 0 0 0-1.097 1.097l-.387 1.162a.217.217 0 0 1-.412 0l-.387-1.162A1.734 1.734 0 0 0 9.31 6.593l-1.162-.387a.217.217 0 0 1 0-.412l1.162-.387a1.734 1.734 0 0 0 1.097-1.097l.387-1.162zM13.863.099a.145.145 0 0 1 .274 0l.258.774c.115.346.386.617.732.732l.774.258a.145.145 0 0 1 0 .274l-.774.258a1.156 1.156 0 0 0-.732.732l-.258.774a.145.145 0 0 1-.274 0l-.258-.774a1.156 1.156 0 0 0-.732-.732l-.774-.258a.145.145 0 0 1 0-.274l.774-.258c.346-.115.617-.386.732-.732L13.863.1z\" />\n    </symbol>\n    <symbol id=\"sun-fill\" viewBox=\"0 0 16 16\">\n      <path\n        d=\"M8 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8zM8 0a.5.5 0 0 1 .5.5v2a.5.5 0 0 1-1 0v-2A.5.5 0 0 1 8 0zm0 13a.5.5 0 0 1 .5.5v2a.5.5 0 0 1-1 0v-2A.5.5 0 0 1 8 13zm8-5a.5.5 0 0 1-.5.5h-2a.5.5 0 0 1 0-1h2a.5.5 0 0 1 .5.5zM3 8a.5.5 0 0 1-.5.5h-2a.5.5 0 0 1 0-1h2A.5.5 0 0 1 3 8zm10.657-5.657a.5.5 0 0 1 0 .707l-1.414 1.415a.5.5 0 1 1-.707-.708l1.414-1.414a.5.5 0 0 1 .707 0zm-9.193 9.193a.5.5 0 0 1 0 .707L3.05 13.657a.5.5 0 0 1-.707-.707l1.414-1.414a.5.5 0 0 1 .707 0zm9.193 2.121a.5.5 0 0 1-.707 0l-1.414-1.414a.5.5 0 0 1 .707-.707l1.414 1.414a.5.5 0 0 1 0 .707zM4.464 4.465a.5.5 0 0 1-.707 0L2.343 3.05a.5.5 0 1 1 .707-.707l1.414 1.414a.5.5 0 0 1 0 .708z\" />\n    </symbol>\n  </svg>\n\n  <div class=\"dropdown position-fixed bottom-0 end-0 mb-3 me-3 bd-mode-toggle\">\n    <button class=\"btn btn-bd-primary py-2 dropdown-toggle d-flex align-items-center\" id=\"bd-theme\" type=\"button\"\n      aria-expanded=\"false\" data-bs-toggle=\"dropdown\" aria-label=\"Toggle theme (auto)\">\n      <svg class=\"bi my-1 theme-icon-active\" width=\"1em\" height=\"1em\">\n        <use href=\"#circle-half\"></use>\n      </svg>\n      <span class=\"visually-hidden\" id=\"bd-theme-text\">Toggle theme</span>\n    </button>\n    <ul class=\"dropdown-menu dropdown-menu-end shadow\" aria-labelledby=\"bd-theme-text\">\n      <li>\n        <button type=\"button\" class=\"dropdown-item d-flex align-items-center\" data-bs-theme-value=\"light\"\n          aria-pressed=\"false\">\n          <svg class=\"bi me-2 opacity-50\" width=\"1em\" height=\"1em\">\n            <use href=\"#sun-fill\"></use>\n          </svg>\n          Light\n          <svg class=\"bi ms-auto d-none\" width=\"1em\" height=\"1em\">\n            <use href=\"#check2\"></use>\n          </svg>\n        </button>\n      </li>\n      <li>\n        <button type=\"button\" class=\"dropdown-item d-flex align-items-center\" data-bs-theme-value=\"dark\"\n          aria-pressed=\"false\">\n          <svg class=\"bi me-2 opacity-50\" width=\"1em\" height=\"1em\">\n            <use href=\"#moon-stars-fill\"></use>\n          </svg>\n          Dark\n          <svg class=\"bi ms-auto d-none\" width=\"1em\" height=\"1em\">\n            <use href=\"#check2\"></use>\n          </svg>\n        </button>\n      </li>\n      <li>\n        <button type=\"button\" class=\"dropdown-item d-flex align-items-center active\" data-bs-theme-value=\"auto\"\n          aria-pressed=\"true\">\n          <svg class=\"bi me-2 opacity-50\" width=\"1em\" height=\"1em\">\n            <use href=\"#circle-half\"></use>\n          </svg>\n          Auto\n          <svg class=\"bi ms-auto d-none\" width=\"1em\" height=\"1em\">\n            <use href=\"#check2\"></use>\n          </svg>\n        </button>\n      </li>\n    </ul>\n  </div>\n\n\n  <div class=\"container\">\n    <main>\n      <div class=\"py-5 text-center\">\n        <img class=\"d-block mx-auto mb-4\" src=\"../assets/brand/bootstrap-logo.svg\" alt=\"\" width=\"72\" height=\"57\">\n        <h2>Checkout form</h2>\n        <p class=\"lead\">Below is an example form built entirely with Bootstrap’s form controls. Each required form group\n          has a validation state that can be triggered by attempting to submit the form without completing it.</p>\n      </div>\n\n      <div class=\"row g-5\">\n        <div class=\"col-md-5 col-lg-4 order-md-last\">\n          <h4 class=\"d-flex justify-content-between align-items-center mb-3\">\n            <span class=\"text-primary\">Your cart</span>\n            <span class=\"badge bg-primary rounded-pill\">3</span>\n          </h4>\n          <ul class=\"list-group mb-3\">\n            <li class=\"list-group-item d-flex justify-content-between lh-sm\">\n              <div>\n                <h6 class=\"my-0\">Product name</h6>\n                <small class=\"text-body-secondary\">Brief description</small>\n              </div>\n              <span class=\"text-body-secondary\">$12</span>\n            </li>\n            <li class=\"list-group-item d-flex justify-content-between lh-sm\">\n              <div>\n                <h6 class=\"my-0\">Second product</h6>\n                <small class=\"text-body-secondary\">Brief description</small>\n              </div>\n              <span class=\"text-body-secondary\">$8</span>\n            </li>\n            <li class=\"list-group-item d-flex justify-content-between lh-sm\">\n              <div>\n                <h6 class=\"my-0\">Third item</h6>\n                <small class=\"text-body-secondary\">Brief description</small>\n              </div>\n              <span class=\"text-body-secondary\">$5</span>\n            </li>\n            <li class=\"list-group-item d-flex justify-content-between bg-body-tertiary\">\n              <div class=\"text-success\">\n                <h6 class=\"my-0\">Promo code</h6>\n                <small>EXAMPLECODE</small>\n              </div>\n              <span class=\"text-success\">−$5</span>\n            </li>\n            <li class=\"list-group-item d-flex justify-content-between\">\n              <span>Total (USD)</span>\n              <strong>$20</strong>\n            </li>\n          </ul>\n\n          <form class=\"card p-2\">\n            <div class=\"input-group\">\n              <input type=\"text\" class=\"form-control\" placeholder=\"Promo code\">\n              <button type=\"submit\" class=\"btn btn-secondary\">Redeem</button>\n            </div>\n          </form>\n        </div>\n        <div class=\"col-md-7 col-lg-8\">\n          <h4 class=\"mb-3\">Billing address</h4>\n          <form class=\"needs-validation\" novalidate>\n            <div class=\"row g-3\">\n              <div class=\"col-sm-6\">\n                <label for=\"firstName\" class=\"form-label\">First name</label>\n                <input type=\"text\" class=\"form-control\" id=\"firstName\" placeholder=\"\" value=\"\" required>\n                <div class=\"invalid-feedback\">\n                  Valid first name is required.\n                </div>\n              </div>\n\n              <div class=\"col-sm-6\">\n                <label for=\"lastName\" class=\"form-label\">Last name</label>\n                <input type=\"text\" class=\"form-control\" id=\"lastName\" placeholder=\"\" value=\"\" required>\n                <div class=\"invalid-feedback\">\n                  Valid last name is required.\n                </div>\n              </div>\n\n              <div class=\"col-12\">\n                <label for=\"username\" class=\"form-label\">Username</label>\n                <div class=\"input-group has-validation\">\n                  <span class=\"input-group-text\">@</span>\n                  <input type=\"text\" class=\"form-control\" id=\"username\" placeholder=\"Username\" required>\n                  <div class=\"invalid-feedback\">\n                    Your username is required.\n                  </div>\n                </div>\n              </div>\n\n              <div class=\"col-12\">\n                <label for=\"email\" class=\"form-label\">Email <span class=\"text-body-secondary\">(Optional)</span></label>\n                <input type=\"email\" class=\"form-control\" id=\"email\" placeholder=\"you@example.com\">\n                <div class=\"invalid-feedback\">\n                  Please enter a valid email address for shipping updates.\n                </div>\n              </div>\n\n              <div class=\"col-12\">\n                <label for=\"address\" class=\"form-label\">Address</label>\n                <input type=\"text\" class=\"form-control\" id=\"address\" placeholder=\"1234 Main St\" required>\n                <div class=\"invalid-feedback\">\n                  Please enter your shipping address.\n                </div>\n              </div>\n\n              <div class=\"col-12\">\n                <label for=\"address2\" class=\"form-label\">Address 2 <span\n                    class=\"text-body-secondary\">(Optional)</span></label>\n                <input type=\"text\" class=\"form-control\" id=\"address2\" placeholder=\"Apartment or suite\">\n              </div>\n\n              <div class=\"col-md-5\">\n                <label for=\"country\" class=\"form-label\">Country</label>\n                <select class=\"form-select\" id=\"country\" required>\n                  <option value=\"\">Choose...</option>\n                  <option>United States</option>\n                </select>\n                <div class=\"invalid-feedback\">\n                  Please select a valid country.\n                </div>\n              </div>\n\n              <div class=\"col-md-4\">\n                <label for=\"state\" class=\"form-label\">State</label>\n                <select class=\"form-select\" id=\"state\" required>\n                  <option value=\"\">Choose...</option>\n                  <option>California</option>\n                </select>\n                <div class=\"invalid-feedback\">\n                  Please provide a valid state.\n                </div>\n              </div>\n\n              <div class=\"col-md-3\">\n                <label for=\"zip\" class=\"form-label\">Zip</label>\n                <input type=\"text\" class=\"form-control\" id=\"zip\" placeholder=\"\" required>\n                <div class=\"invalid-feedback\">\n                  Zip code required.\n                </div>\n              </div>\n            </div>\n\n            <hr class=\"my-4\">\n\n            <div class=\"form-check\">\n              <input type=\"checkbox\" class=\"form-check-input\" id=\"same-address\">\n              <label class=\"form-check-label\" for=\"same-address\">Shipping address is the same as my billing\n                address</label>\n            </div>\n\n            <div class=\"form-check\">\n              <input type=\"checkbox\" class=\"form-check-input\" id=\"save-info\">\n              <label class=\"form-check-label\" for=\"save-info\">Save this information for next time</label>\n            </div>\n\n            <hr class=\"my-4\">\n\n            <h4 class=\"mb-3\">Payment</h4>\n\n            <div class=\"my-3\">\n              <div class=\"form-check\">\n                <input id=\"credit\" name=\"paymentMethod\" type=\"radio\" class=\"form-check-input\" checked required>\n                <label class=\"form-check-label\" for=\"credit\">Credit card</label>\n              </div>\n              <div class=\"form-check\">\n                <input id=\"debit\" name=\"paymentMethod\" type=\"radio\" class=\"form-check-input\" required>\n                <label class=\"form-check-label\" for=\"debit\">Debit card</label>\n              </div>\n              <div class=\"form-check\">\n                <input id=\"paypal\" name=\"paymentMethod\" type=\"radio\" class=\"form-check-input\" required>\n                <label class=\"form-check-label\" for=\"paypal\">PayPal</label>\n              </div>\n            </div>\n\n            <div class=\"row gy-3\">\n              <div class=\"col-md-6\">\n                <label for=\"cc-name\" class=\"form-label\">Name on card</label>\n                <input type=\"text\" class=\"form-control\" id=\"cc-name\" placeholder=\"\" required>\n                <small class=\"text-body-secondary\">Full name as displayed on card</small>\n                <div class=\"invalid-feedback\">\n                  Name on card is required\n                </div>\n              </div>\n\n              <div class=\"col-md-6\">\n                <label for=\"cc-number\" class=\"form-label\">Credit card number</label>\n                <input type=\"text\" class=\"form-control\" id=\"cc-number\" placeholder=\"\" required>\n                <div class=\"invalid-feedback\">\n                  Credit card number is required\n                </div>\n              </div>\n\n              <div class=\"col-md-3\">\n                <label for=\"cc-expiration\" class=\"form-label\">Expiration</label>\n                <input type=\"text\" class=\"form-control\" id=\"cc-expiration\" placeholder=\"\" required>\n                <div class=\"invalid-feedback\">\n                  Expiration date required\n                </div>\n              </div>\n\n              <div class=\"col-md-3\">\n                <label for=\"cc-cvv\" class=\"form-label\">CVV</label>\n                <input type=\"text\" class=\"form-control\" id=\"cc-cvv\" placeholder=\"\" required>\n                <div class=\"invalid-feedback\">\n                  Security code required\n                </div>\n              </div>\n            </div>\n\n            <hr class=\"my-4\">\n\n            <button class=\"w-100 btn btn-primary btn-lg\" type=\"submit\">Continue to checkout</button>\n          </form>\n        </div>\n      </div>\n    </main>\n\n    <footer class=\"my-5 pt-5 text-body-secondary text-center text-small\">\n      <p class=\"mb-1\">&copy; 2017–2024 Company Name</p>\n      <ul class=\"list-inline\">\n        <li class=\"list-inline-item\"><a href=\"#\">Privacy</a></li>\n        <li class=\"list-inline-item\"><a href=\"#\">Terms</a></li>\n        <li class=\"list-inline-item\"><a href=\"#\">Support</a></li>\n      </ul>\n    </footer>\n  </div>\n  <script src=\"checkout.js\"></script>\n<!-- /wp:html -->', 'Checkout', '', 'publish', 'closed', 'closed', '', 'checkout', '', '', '2024-04-28 23:53:10', '2024-04-28 23:53:10', '', 0, 'https://local.theatrumdev/?page_id=14', 0, 'page', '', 0),
