 <td>dashboard</td>\n                <td>irrelevant</td>\n                <td>text</td>\n                <td>placeholder</td>\n              </tr>\n              <tr>\n                <td>1,006</td>\n                <td>dashboard</td>\n                <td>illustrative</td>\n                <td>rich</td>\n                <td>data</td>\n              </tr>\n              <tr>\n                <td>1,007</td>\n                <td>placeholder</td>\n                <td>tabular</td>\n                <td>information</td>\n                <td>irrelevant</td>\n              </tr>\n              <tr>\n                <td>1,008</td>\n                <td>random</td>\n                <td>data</td>\n                <td>placeholder</td>\n                <td>text</td>\n              </tr>\n              <tr>\n                <td>1,009</td>\n                <td>placeholder</td>\n                <td>irrelevant</td>\n                <td>visual</td>\n                <td>layout</td>\n              </tr>\n              <tr>\n                <td>1,010</td>\n                <td>data</td>\n                <td>rich</td>\n                <td>dashboard</td>\n                <td>tabular</td>\n              </tr>\n              <tr>\n                <td>1,011</td>\n                <td>information</td>\n                <td>placeholder</td>\n                <td>illustrative</td>\n                <td>data</td>\n              </tr>\n              <tr>\n                <td>1,012</td>\n                <td>text</td>\n                <td>placeholder</td>\n                <td>layout</td>\n                <td>dashboard</td>\n              </tr>\n              <tr>\n                <td>1,013</td>\n                <td>dashboard</td>\n                <td>irrelevant</td>\n                <td>text</td>\n                <td>visual</td>\n              </tr>\n              <tr>\n                <td>1,014</td>\n                <td>dashboard</td>\n                <td>illustrative</td>\n                <td>rich</td>\